INSERT INTO assessments (assessment_id, paper_version_id, assessment_type, model_run_id, schema_version, rubric_id, rubric_version, status, paper_summary, overall_score, overall_rating, reading_recommendation, confidence, is_provisional, stage, provisional_reason, overall_assessment, strengths, concerns, unresolved_questions, limitations_of_assessment, guardrails)
VALUES ('assessment_ai_paper_001_v3', 'paper_001_v3', 'ai', 'model_run_codex_review_paper_001_v3', '0.5.0', 'iclr_inspired_due_diligence', '0.1-draft', 'approved', 'TAFT linearizes pretrained transformers to enable efficient composition, parallel training, shard-based removal and private fine-tuning, evaluated on visual classification.', 7.6, 'good', 'worth_reading_with_checks', 'medium', FALSE, 'report_ready', NULL, 'A valuable and clearly positioned method with broad enabling ideas. Its central feasibility evidence is credible, but the empirical scope is one backbone/task family and reported margins lack run-to-run uncertainty.', '["Connects one linearization mechanism to composition, unlearning and privacy.", "Tests the mechanism on seven downstream datasets with ablations and cost comparisons.", "States important limits, including initialization sensitivity and potentially doubled inference cost."]'::jsonb, '["No variance, confidence interval or repeated-run evidence is reported for central margins.", "Average TAFT accuracy is slightly below nonlinear fine-tuning and degrades on distant domains.", "Hardware/software and the fixed random-seed value are not disclosed."]'::jsonb, '["Are reported gains stable across seeds?", "How well does the method transfer beyond visual classification and ViT-L/16?"]'::jsonb, '["Paper-internal evidence only.", "No experiment or code was executed.", "Originality evaluates the paper''s positioning rather than an exhaustive prior-art search."]'::jsonb, '{"experiments_reproduced": false, "accept_reject_prediction_made": false, "external_reviews_used_for_scoring": false}'::jsonb)
