INSERT INTO papers (paper_id, title, authors, authors_status, language, arxiv_id, openreview_forum_id, venue, publication_year, abstract, doi)
VALUES ('paper_003', 'MemStranding: Adversarial Attacks on Temporal Graph Neural Networks', '[]'::jsonb, 'anonymous_at_assessed_version', 'en', NULL, 'Pmrc0nEvxf', 'ICLR', 2024, 'Temporal graph neural networks (TGNN) have achieved significant momentum in many real-world dynamic graph tasks. While this trend raises an urgent to study their robustness against adversarial attacks, developing an attack on TGNN is challenging due to the dynamic nature of their input dynamic graphs. On the one hand, subsequent graph changes after the attacks may diminish the impact of attacks on seen nodes. On the other hand, targeting future nodes, which are unseen during the attack, poses significant challenges due to missing knowledge about them. To tackle these unique challenges in attacking TGNNs, we propose a practical and effective adversarial attack framework, MemStranding, that leverages node memories in TGNN models to yield long-lasting and spreading adversarial noises in dynamic graphs. The MemStranding allows the attacker to inject noises into nodes’ memory by adding fake nodes/edges at arbitrary timestamps. During future updates, the noises in nodes will persist with the support from their neighbors and be propagated to the future nodes by molding their memories into similar noisy states. The experimental results demonstrate that MemStranding can significantly decrease the TGNN models’ performances in various tasks.', NULL)
ON CONFLICT DO NOTHING;

