INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_004_v1_chunk_0015', 'paper_004_v1', 'paper_004_v1_sec_3_5', 15, 0, 8, 8, 'body_text', 'The selection mechanism is a broader concept that can be applied in different ways, such as to more traditional RNNs or CNNs, to different parameters (e.g. A in Algorithm 2), or using different transformations 𝑠(𝑥) .', 47, 216, 'high')
