VALUES ('paper_004_v1_chunk_0020', 'paper_004_v1', 'paper_004_v1_sec_4_1', 20, 0, 10, 10, 'body_text', 'Full experiment details for these tasks including task details and training protocol are in Appendix E.1.', 21, 105, 'high')
