INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_004_v1_chunk_0034', 'paper_004_v1', 'paper_004_v1_sec_4_6', 34, 0, 16, 16, 'body_text', 'We perform a series of detailed ablations on components of our model, focusing on the setting of language modeling with size ≈ 350 M models at Chinchilla token counts (same setting as Figure 4).', 44, 194, 'high')
