INSERT INTO assessments (assessment_id, paper_version_id, assessment_type, model_run_id, schema_version, rubric_id, rubric_version, status, paper_summary, overall_score, overall_rating, reading_recommendation, confidence, is_provisional, stage, provisional_reason, overall_assessment, strengths, concerns, unresolved_questions, limitations_of_assessment, guardrails)
VALUES ('assessment_ai_paper_004_v1', 'paper_004_v1', 'ai', 'model_run_codex_review_paper_004_v1', '0.5.0', 'iclr_inspired_due_diligence', '0.1-draft', 'approved', 'Mamba introduces input-dependent selective state-space models and a hardware-aware parallel scan, delivering linear sequence scaling and strong results across language, DNA and audio.', 8.6, 'strong', 'worth_deep_reading', 'medium', FALSE, 'report_ready', NULL, 'A high-value, original and extensively evaluated architecture paper. Evidence spans synthetic mechanism tests, scaling studies, downstream tasks and efficiency benchmarks, with unusually strong implementation availability.', '["Links a clear modeling limitation of LTI state-space models to an input-dependent selection mechanism.", "Combines algorithmic and hardware-aware contributions rather than reporting accuracy alone.", "Evaluates language, DNA, audio, long-context behavior, ablations, speed and memory."]'::jsonb, '["Some comparisons use different training regimes or parameter budgets, complicating causal attribution.", "The paper covers many modalities but detailed failure analysis is limited.", "Several efficiency conclusions are hardware- and implementation-dependent."]'::jsonb, '["How robust are gains under matched-data and matched-compute comparisons?", "Which selection components drive performance in the largest models?"]'::jsonb, '["Paper-internal evidence only.", "No experiment or code was executed.", "Originality evaluates the paper''s positioning rather than an exhaustive prior-art search."]'::jsonb, '{"experiments_reproduced": false, "accept_reject_prediction_made": false, "external_reviews_used_for_scoring": false}'::jsonb)
ON CONFLICT DO NOTHING;

