INSERT INTO assessments (assessment_id, paper_version_id, assessment_type, model_run_id, schema_version, rubric_id, rubric_version, status, paper_summary, overall_score, overall_rating, reading_recommendation, confidence, is_provisional, stage, provisional_reason, overall_assessment, strengths, concerns, unresolved_questions, limitations_of_assessment, guardrails)
VALUES ('assessment_ai_paper_006_v3', 'paper_006_v3', 'ai', 'model_run_codex_review_paper_006_v3', '0.5.0', 'iclr_inspired_due_diligence', '0.1-draft', 'approved', 'MathVista consolidates and extends visual mathematical reasoning datasets, supplies a broad taxonomy and evaluates twelve foundation models with detailed quantitative and qualitative analysis.', 8.4, 'good', 'worth_reading_with_checks', 'medium', FALSE, 'report_ready', NULL, 'A highly useful benchmark paper with broad coverage, public resources, explicit protocols and unusually extensive analysis. Dataset composition and model-dependent answer extraction remain important limitations.', '["Combines 28 existing datasets with three newly created datasets under a coherent taxonomy.", "Reports human and model baselines across reasoning skills, tasks and visual contexts.", "Publishes prompts, model settings, examples and fine-grained error analyses."]'::jsonb, '["A GPT-4-based answer extractor may introduce model-dependent evaluation bias.", "Aggregation of many source datasets inherits heterogeneous annotation and licensing conditions.", "Some proprietary-model evaluations are difficult to reproduce exactly."]'::jsonb, '["How stable are rankings under alternative answer extractors?", "How should future versions control source-dataset contamination in pretrained models?"]'::jsonb, '["Paper-internal evidence only.", "No experiment or code was executed.", "Originality evaluates the paper''s positioning rather than an exhaustive prior-art search."]'::jsonb, '{"experiments_reproduced": false, "accept_reject_prediction_made": false, "external_reviews_used_for_scoring": false}'::jsonb)
ON CONFLICT DO NOTHING;

