INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_006_ev_001', 'assessment_ai_paper_006_v3', 'paper_006_v3_chunk_0001', NULL, 1, 'ABSTRACT', 'text', 'paper_006_v3_chunk_0001', 'quote', 'but their ability in mathematical reasoning in visual contexts has not been systematically studied. To bridge this gap, we present M ATH V ISTA , a benchmark designed to combine challenges from diverse mathematical and visual tasks. It consists of 6,141 examples, derived from 28 existing multimodal datasets involving mathematics and 3 newly created datasets ( i.e. , IQTest, FunctionQA, and PaperQA). Completing these tasks requires fine-grained, deep visual understanding and compositional reasoning, which all state-of-the-art foundation models find challenging. With M ATH V ISTA , we have conducted a comprehensive, quantitative evaluation of12', 'high', 'paper_006_v3_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_006_ev_002', 'assessment_ai_paper_006_v3', 'paper_006_v3_chunk_0001', NULL, 1, 'ABSTRACT', 'text', 'paper_006_v3_chunk_0001', 'quote', 'ducted a comprehensive, quantitative evaluation of12prominentfoundationmodels. Thebest-performingGPT-4Vmodelachieves an overall accuracy of 49.9%, substantially outperforming Bard, the second-best performer, by 15.1%. Our in-depth analysis reveals that the superiority of GPT- 4V is mainly attributed to its enhanced visual perception and mathematical reasoning. However, GPT-4V still falls short of human performance by 10.4%, as it often struggles to understand complex figures and perform rigorous reasoning. This significant gap underscores the critical role that M ATH V ISTA will play in the development of general-purpose AI agents capable of', 'high', 'paper_006_v3_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_006_ev_003', 'assessment_ai_paper_006_v3', 'paper_006_v3_chunk_0004', NULL, 3, 'INTRODUCTION', 'text', 'paper_006_v3_chunk_0004', 'quote', 'nations caused by visual perception and textual reasoning (§3.5).

