INSERT INTO assessments (assessment_id, paper_version_id, assessment_type, model_run_id, schema_version, rubric_id, rubric_version, status, paper_summary, overall_score, overall_rating, reading_recommendation, confidence, is_provisional, stage, provisional_reason, overall_assessment, strengths, concerns, unresolved_questions, limitations_of_assessment, guardrails)
VALUES ('assessment_ai_paper_007_openreview_2024_02_11', 'paper_007_openreview_2024_02_11', 'ai', 'model_run_codex_review_paper_007_openreview_2024_02_11', '0.5.0', 'iclr_inspired_due_diligence', '0.1-draft', 'approved', 'Large language models are trained on vast amounts of internet data, prompting concerns that they have memorized public benchmarks. Detecting this type of contamination is challenging because the pretraining data used by proprietary models are often not publicly accessible.', 8.0, 'good', 'worth_reading_with_checks', 'medium', FALSE, 'report_ready', NULL, 'Codex 会话依据《Proving Test Set Contamination in Black-Box Language Models》锁定 PDF 中的可定位正文，对五个维度进行了独立暂定评估。总分 8.0/10 由五维等权计算；结论受论文自身实验范围、披露程度和未执行复现实验的限制。', '["正文可定位证据支持该维度判断：Large language models are trained on vast amounts of internet data, prompting concerns and speculation that they have memorized public benchmarks. ", "正文可定位证据支持该维度判断：The core idea of our statistical test is to compare the log probability of the dataset under its original ordering to the log probability under random permutations. ", "正文可定位证据支持该维度判断：We list in table 4 the full set of MMLU results used to generate the omnibus p-values for contamination by MMLU listed in table 2, before filtering out for suspected non-exchangeability."]'::jsonb, '["评分受以下论文内边界约束：We highlight a few limitations of our approach for detecting test set contamination. "]'::jsonb, '["How stable are the central findings under additional seeds, settings or datasets?", "Which conclusions remain valid outside the evaluated scope?"]'::jsonb, '["Paper-internal evidence only.", "No experiment or code was executed.", "Originality is not an exhaustive prior-art search."]'::jsonb, '{"experiments_reproduced": false, "accept_reject_prediction_made": false, "external_reviews_used_for_scoring": false}'::jsonb)
ON CONFLICT DO NOTHING;

