INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_009_openreview_2024_02_11_descriptor_001', 'paper_009_openreview_2024_02_11', 'research_problem', 'problem_statement', 'Deep neural networks (DNNs) trained for image denoising are able to generate high-quality samples with score-based reverse diffusion algorithms. These impressive capabilities seem to imply an escape from the curse of dimensionality, but recent reports of memorization of the training set raise the question of whether these networks are learning the "true" continuous density of the data.', 'paper_009_openreview_2024_02_11_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_009_openreview_2024_02_11_descriptor_002', 'paper_009_openreview_2024_02_11', 'contributions', 'claimed_contribution', 'Here, we show that two DNNs trained on non-overlapping subsets of a dataset learn nearly the same score function, and thus the same density, when the number of training images is large enough.', 'paper_009_openreview_2024_02_11_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

