INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_011_openreview_2024_02_11_chunk_0000', 'paper_011_openreview_2024_02_11', 'paper_011_openreview_2024_02_11_sec_front_matter', 0, 0, 1, 1, 'body_text', 'T HE MECHANISTIC BASIS OF DATA DEPENDENCE AND ABRUPT LEARNING IN AN IN - CONTEXT CLASSIFICA - TION TASK

Gautam Reddy ∗ Department of Physics, Princeton University Physics & Informatics Laboratories, NTT Research Inc. Center for Brain Science, Harvard University', 52, 262, 'high')
