INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_013_ev_005', 'assessment_ai_paper_013_openreview_2024_02_11', 'paper_013_openreview_2024_02_11_chunk_0002', NULL, 1, NULL, 'text', 'paper_013_openreview_2024_02_11_chunk_0002', 'quote', 'Despite tremendous advances in machine learning, a large gap still exists between humans and machines in terms of learning efficiency and generalization (Tenenbaum et al., 2011; Behrens et al., 2018; Sch olkopf ¨ et al., 2021). A key reason for this is thought to be that machines lack the ability to generalize compositionally , which humans heavily rely on (Fodor and Pylyshyn, 1988; Lake et al., 2017; Battaglia et al., 2018; Goyal and Bengio, 2022; Greff et al., 2020). Namely, humans are able to recompose previously learned knowledge to generalize to never-before-seen situations. Significant work has thus gone into the problem of learning representations that can generalize compositionally. One prominent effort is object-centric representation learning (Burgess et al., 2019; Greff et al., 2019; Locatello et al., 2020a; Lin et al., 2020; Singh et al., 2022; Elsayed et al., 2022; Seitzer e', 'high', 'paper_013_openreview_2024_02_11_sec_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

