VALUES ('paper_014_openreview_2024_02_11_chunk_0008', 'paper_014_openreview_2024_02_11', 'paper_014_openreview_2024_02_11_sec_3_2', 8, 1, 5, 5, 'body_text', 'similarities Information flow weights values

