INSERT INTO paper_elements (element_id, paper_version_id, section_id, element_type, label, caption, page_number, extracted_text, asset_object_key, parse_quality)
VALUES ('paper_015_openreview_2024_02_11_figure_1', 'paper_015_openreview_2024_02_11', 'paper_015_openreview_2024_02_11_sec_2', 'figure', 'Figure 1', 'Boosting of thoughts iteratively enhances the prompt by adding experience , which comprises the analysis conducted by large language models (LLM or LM) on the generated thought chain. The experience specifically contains the thought chain itself, the corresponding error reports, and detailed advice on revising each reasoning step. Thus, those ineffective thoughts marked with a red cross can also contribute to prompt refinement. By accumulating experiences over iterations in the prompt, BoT can eventually yield a correct', 2, NULL, 'renders/paper_015/openreview_2024_02_11/page-0002.png', 'good')
ON CONFLICT DO NOTHING;

INSERT INTO paper_elements (element_id, paper_version_id, section_id, element_type, label, caption, page_number, extracted_text, asset_object_key, parse_quality)
