INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_015_ev_001', 'assessment_ai_paper_015_openreview_2024_02_11', 'paper_015_openreview_2024_02_11_chunk_0001', NULL, 1, NULL, 'text', 'paper_015_openreview_2024_02_11_chunk_0001', 'quote', 'The reasoning performance of Large Language Models (LLMs) on a wide range of problems critically relies on chain-of-thought prompting, which involves providing a few chain of thought demonstrations as exemplars in prompts. Recent work, e.g., Tree of Thoughts, has pointed out the importance of exploration and selfevaluation in reasoning step selection for complex problem solving. In this paper, we present Boosting of Thoughts (BoT), an automated prompting framework for problem solving with LLMs by iteratively exploring and self-evaluating many trees of thoughts in order to acquire an ensemble of trial-and-error reasoning experiences, which will serve as a new form of prompting to solve the complex problem. Starting from a simple prompt without requiring examples, BoT iteratively explores and evaluates a large collection of reasoning steps, and more importantly, uses error analysis obtaine', 'high', 'paper_015_openreview_2024_02_11_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_015_ev_002', 'assessment_ai_paper_015_openreview_2024_02_11', 'paper_015_openreview_2024_02_11_chunk_0053', NULL, 28, NULL, 'text', 'paper_015_openreview_2024_02_11_chunk_0053', 'quote', 'ExperienceobtainedinIteration1 ########The1-thReasoningChainwithComments######## Belowisareasoningchaincontainingreasoningstepspresentedinorder: ———————————– Step1:ConvertthefractionsoftheskeinofyarnusedbyMariahandhergrandmaintoyards. Mariahused1/4ofaskein,whichequals1/4*364yards. Her grandmaused1/2ofaskein,whichequals1/2*364yards..EvaluateScore:1.0 Step2:CalculatethetotalyardsofyarnusedbybothMariahandhergrandmabyaddingtheyardsofyarnMariahusedandtheyardsofyarnhergrandmaused.. EvaluateScore:1.0 Step1:ConvertthefractionsoftheskeinofyarnusedbyMariahandhergrandmaintoyards.Mariahused1/4ofaskein,whichequals1/4*364yards=91yards. Hergrandmaused1/2ofaskein,whichequals1/2*364yards=182yards..EvaluateScore:1.0 ———————————– AnalysisReport:Thereasoningchaincancompletethetaskandreachthetargetcorrectlybyexecutingitsreasoningsteps.Thestepsarelogical,followaclear progression,andarenecessaryforsolvingthepr', 'high', 'paper_015_openreview_2024_02_11_sec_h', NULL, FALSE)
