INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_016_openreview_2024_02_11_chunk_0031', 'paper_016_openreview_2024_02_11', 'paper_016_openreview_2024_02_11_sec_e', 31, 0, 16, 18, 'body_text', 'We provide more implementation details of Losse-FTL in this section. Referring to Figure 3, the input x is first pre-processed to be bounded between [ 3 , 3] , and then projected with a matrix t − 2 https://github.com/jannerm/mbpo

containing values sampled from an isotropic Gaussian with µ = 0 and Σ = 1 I , where c is the fanc in dimension, i.e., S + A . This ensures the projected values σ ( x ) are bounded with high probability t and facilitates a more even bin utilization. In computing the sparse update at line 7 of Algorithm 2, we use ( A + ε I ) − 1 for some small ε > 0 to ensure its invertibility. We provide Jax-based Python t,ss codes in Listing 1.

1 import math 2 from typing import NamedTuple, Tuple

4 import chex 5 import jax 6 import jax.numpy as jnp 7 import numpy as np

10 class LosseParams(NamedTuple): 11 count: jax.Array 12 projection: jax.Array 13 xtx: jax.Array 14 xty: jax.Array 15 w: jax.Array

18 def _to_1d_index(indices, offsets, n_feat, bin_dim, n_bins): 19 """Compute the flattened index into the weight matrix.""" 20 n_grids_per_lsh = (n_bins + 1) ** bin_dim 21 indices = jnp.reshape(indices, (-1, bin_dim, n_feat)) 22 offsets = jnp.reshape(offsets, (-1, bin_dim, n_feat)) 23 indices = jnp.stack([indices, indices + 1], axis=-1) # [-1, bin_dim, n_feat, 2] 24 values = jnp.stack([1.0 - offsets, offsets], axis=-1) # [-1, bin_dim, n_feat, 2] 25 multiplier = jnp.power(n_bins + 1, jnp.arange(bin_dim - 1, -1, -1)) 26 indices *= multiplier[:, None , None ] 27 # shape = (-1, n_feat, ) + (2,) * bin_dim 28 shape_suffix = [tuple(*p) for p in np.split(np.eye(bin_dim, dtype=np.int32) + 1, (cid:44) → bin_dim)] 29 indices = sum(jnp.reshape(indices[:, i], (-1, n_feat, *suffix)) for i, suffix in (cid:44) → enumerate(shape_suffix)) 30 values = math.prod(jnp.reshape(values[:, i], (-1, n_feat, *suffix)) for i, suffix in (cid:44) → enumerate(shape_suffix)) 31 # both indices and values has the shape (-1, n_feat, *(2,)*bin_dim) now. 32 indices += jnp.expand_dims( 33 n_grids_per_lsh * jnp.arange(n_feat), axis=tuple(range(-bin_dim, 1, 1)) 34 ) # expand 1 dim in the front and bin_dim in the back. 35 indices = jnp.reshape(indices, (-1, n_feat * 2**bin_dim)) 36 values = jnp.reshape(values, (-1, n_feat * 2**bin_dim)) 37 return indices, values

40 class Losse: 41 """Linear regressor with LOcality Sensitive Sparse Encoding (Losse).

43 We update the linear weights online sparsely following Algorithm.2 in the paper, i.e., (cid:44) → computing the incremental closed-form solution based on newly incoming data points. 44 """

46 def __init__( 47 self, 48 inout_dims: Tuple[int, int], 49 num_features: int, 50 num_bins: int, 51 bin_dim: int, 52 eps: float, 53 ) -> None : 54 self.num_features = num_features 55 self.num_bins = num_bins 56 self.bin_dim = bin_dim 57 self.inout_dims = inout_dims 58 self.eps = eps 59 n_edges = num_bins + 1 60 n_grids_per_lsh = (n_edges + 1) ** bin_dim 61 self.d = n_grids_per_lsh * num_features

63 def init(self, rng: jax.random.PRNGKey) -> LosseParams: 64 input_dim = self.inout_dims[0] 65 output_dim = self.inout_dims[1] 66 std = 1 / jnp.sqrt(input_dim) 67 projection = std * jax.random.truncated_normal( 68 rng, 69 -2,

70 2, 71 (input_dim, self.num_features * self.bin_dim), 72 ) 73 return LosseParams( 74 count=jnp.array(0, dtype=jnp.int64), 75 projection=projection, 76 xtx=jnp.zeros((self.d * self.d,), dtype=projection.dtype), 77 xty=jnp.zeros((self.d, output_dim), dtype=projection.dtype), 78 w=jnp.zeros((self.d, output_dim), dtype=projection.dtype), 79 )', 701, 3524, 'high')
ON CONFLICT DO NOTHING;

INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_016_openreview_2024_02_11_chunk_0032', 'paper_016_openreview_2024_02_11', 'paper_016_openreview_2024_02_11_sec_e', 32, 1, 18, 19, 'body_text', '81 def update( 82 self, 83 params: LosseParams, 84 x: jax.Array, 85 y: jax.Array, 86 ) -> LosseParams: 87 chex.assert_tree_shape_prefix((x, y), (1,)) # assert non-batched 88 indices, values = self._indices_and_values(params.projection, x) 89 params = self._update_memory(params, indices, values, y) 90 params = self._update_w(params, indices) 91 return params

93 def predict(self, params: LosseParams, x: jax.Array): 94 indices, values = self._indices_and_values(params.projection, x) 95 output = params.w[indices] * values[..., None ] 96 return output.sum(1)

98 def _indices_and_values( 99 self, 100 projection: jax.Array, 101 x: jax.Array, 102 ): 103 h = jnp.matmul(x, projection) 104 h = jax.nn.sigmoid(h) 105 h = jnp.clip(h, 0, 1) * self.num_bins 106 indices = jnp.floor(h).astype(jnp.int32) 107 offsets = h - indices 108 indices, values = _to_1d_index( 109 indices, 110 offsets, 111 self.num_features, 112 self.bin_dim, 113 self.num_bins, 114 ) 115 return indices, values

117 def _update_memory( 118 self, 119 params: LosseParams, 120 indices: jax.Array, 121 values: jax.Array, 122 y: jax.Array, 123 ) -> LosseParams: 124 chex.assert_equal_shape_prefix((indices, values, y), prefix_len=1) 125 xtx_indices = (indices * self.d)[:, :, None ] + indices[:, None , :] 126 xtx_indices = xtx_indices.flatten() 127 xty_indices = indices.flatten() 128 xtx_updates = values[:, :, None ] * values[:, None ] 129 xtx_updates = xtx_updates.flatten() 130 xty_updates = values[:, :, None ] * y[:, None , :] 131 xty_updates = xty_updates.reshape(-1, y.shape[-1]) 132 return params._replace( 133 xtx=params.xtx.at[xtx_indices].add(xtx_updates), 134 xty=params.xty.at[xty_indices].add(xty_updates), 135 count=params.count + y.shape[0], 136 )

138 def _update_w( 139 self, 140 params: LosseParams, 141 indices: jax.Array, 142 ) -> LosseParams: 143 indices = indices.flatten() 144 sub_indices = (indices * self.d)[:, None ] + indices[ None , :] 145 sub_xtx = jnp.reshape(params.xtx[sub_indices], [indices.shape[0]] * 2) 146 sub_xty = params.xty[indices] 147 a = sub_xtx 148 sub_xtxw = jnp.matmul( 149 jnp.reshape(params.xtx, (self.d, self.d))[indices], 150 params.w,

151 ) 152 b = sub_xty - sub_xtxw + jnp.matmul(sub_xtx, params.w[indices]) 153 a_norm = a / params.count + self.eps * jnp.eye(len(a)) 154 b_norm = b / params.count 155 solution = jnp.linalg.solve(a_norm, b_norm) 156 return params._replace(w=params.w.at[indices].set(solution))

159 losse = Losse( 160 inout_dims=(1, 1), 161 num_features=50, 162 num_bins=10, 163 bin_dim=2, 164 eps=1e-5, 165 )

167 losse.init = jax.jit(losse.init) 168 losse.update = jax.jit(losse.update, donate_argnums=(0,)) # donate to avoid copy 169 losse.predict = jax.jit(losse.predict)

Listing 1: Jax-based Python codes for learning an online linear regressor with Losse-FTL.', 473, 2802, 'high')
