INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_016_ev_005', 'assessment_ai_paper_016_openreview_2024_02_11', 'paper_016_openreview_2024_02_11_chunk_0002', NULL, 1, NULL, 'text', 'paper_016_openreview_2024_02_11_chunk_0002', 'quote', 'World models have been demonstrated to enable sample-efficient model-based reinforcement learning(MBRL)(Sutton,1990;Janneretal.,2019;Kaiseretal.,2020;Schrittwieseretal.,2020), andare deemed as a critical component for next-generation intelligent agents (Sutton et al., 2022; LeCun, 2022). Unfortunately, learning accurate world models in an incremental online manner is challenging, because the data generated from agent-environment interaction is nonstationarily distributed, due to the continually changing policy, state visitation, and even environment dynamics. For neural network (NN) based world models, the nonstationarity could lead to catastrophic forgetting (Mc- Closkey & Cohen, 1989; French, 1999), making models inaccurate at recently under-visited regions (as illustrated in the top row of Figure 1). Planning with inaccurate models is detrimental as the model errors can compound due t', 'high', 'paper_016_openreview_2024_02_11_sec_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_016_ev_006', 'assessment_ai_paper_016_openreview_2024_02_11', 'paper_016_openreview_2024_02_11_chunk_0032', NULL, 18, NULL, 'text', 'paper_016_openreview_2024_02_11_chunk_0032', 'quote', '81 def update( 82 self, 83 params: LosseParams, 84 x: jax.Array, 85 y: jax.Array, 86 ) -> LosseParams: 87 chex.assert_tree_shape_prefix((x, y), (1,)) # assert non-batched 88 indices, values = self._indices_and_values(params.projection, x) 89 params = self._update_memory(params, indices, values, y) 90 params = self._update_w(params, indices) 91 return params

93 def predict(self, params: LosseParams, x: jax.Array): 94 indices, values = self._indices_and_values(params.projection, x) 95 output = params.w[indices] * values[..., None ] 96 return output.sum(1)

98 def _indices_and_values( 99 self, 100 projection: jax.Array, 101 x: jax.Array, 102 ): 103 h = jnp.matmul(x, projection) 104 h = jax.nn.sigmoid(h) 105 h = jnp.clip(h, 0, 1) * self.num_bins 106 indices = jnp.floor(h).astype(jnp.int32) 107 offsets = h - indices 108 indices, values = _to_1d_index( 109 indices, 110 offsets, 111 self.num_f', 'high', 'paper_016_openreview_2024_02_11_sec_e', NULL, FALSE)
ON CONFLICT DO NOTHING;

