INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_018_openreview_2024_02_11_chunk_0000', 'paper_018_openreview_2024_02_11', 'paper_018_openreview_2024_02_11_sec_front_matter', 0, 0, 1, 1, 'body_text', 'B RIDGING V ISION AND L ANGUAGE S PACES WITH A SSIGNMENT P REDICTION

Jungin Park 1 Jiyoung Lee 2 ∗ Kwanghoon Sohn 1 , 3 ∗ 1 Yonsei University 2 NAVER AI Lab 3 Korea Institute of Science and Technology (KIST) { newrun, khsohn } @yonsei.ac.kr lee.j@navercorp.com', 62, 261, 'high')
