VALUES ('paper_018_openreview_2024_02_11_chunk_0023', 'paper_018_openreview_2024_02_11', 'paper_018_openreview_2024_02_11_sec_a', 23, 0, 14, 14, 'body_text', 'In Table 4, we provide hyperparameters used in training.', 12, 56, 'high')
