INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_018_openreview_2024_02_11_chunk_0029', 'paper_018_openreview_2024_02_11', 'paper_018_openreview_2024_02_11_sec_c_1', 29, 1, 16, 16, 'body_text', 'Table 5: Performance comparisons between MAGMA (Eichenberg et al., 2022), LiMBeR (Merullo et al., 2023), FROMAGe (Koh et al., 2023), and VLAP for zero-shot image captioning on the MSCOCO dataset. We report the architectures of visual and language models, BLEU (Papineni et al., 2002), METEOR (Banerjee & Lavie, 2005), ROUGE (Lin, 2004), and SPICE (Anderson et al., 2016).

