INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_018_ev_001', 'assessment_ai_paper_018_openreview_2024_02_11', 'paper_018_openreview_2024_02_11_chunk_0001', NULL, 1, NULL, 'text', 'paper_018_openreview_2024_02_11_chunk_0001', 'quote', 'ThispaperintroducesVLAP,anovelapproachthatbridgespretrainedvisionmodels and large language models (LLMs) to make frozen LLMs understand the visual world. VLAP transforms the embedding space of pretrained vision models into the LLMs’ word embedding space using a single linear layer for efficient and general-purpose visual and language understanding. Specifically, we harnesswell-establishedwordembeddingstobridgetwomodalityembeddingspaces. The visual and text representations are simultaneously assigned to a set of word embeddings within pretrained LLMs by formulating the assigning procedure as an optimal transport problem. We predict the assignment of one modality from the representation of another modality data, enforcing consistent assignments for paired multimodal data. This allows vision and language representations to contain the same information, grounding the frozen LLMs’ word embedd', 'high', 'paper_018_openreview_2024_02_11_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_018_ev_002', 'assessment_ai_paper_018_openreview_2024_02_11', 'paper_018_openreview_2024_02_11_chunk_0017', NULL, 9, NULL, 'text', 'paper_018_openreview_2024_02_11_chunk_0017', 'quote', 'We propose VLAP to bridge pretrained vision encoders and LLMs using a single linear layer for vision-language tasks. VLAP efficiently and effectively learns the linear mapping between image and text data by formulating assignment prediction using LLMs’ word embeddings as the optimal transport. Experimental findings corroborate the effectiveness of VLAP, demonstrating significant performance compared to the previous linear transformation-based methods on a spectrum of visionlanguage tasks. Furthermore, we demonstrate that VLAP holds a semantic taxonomy of LLMs, highlighting the emerging flexibility and applicability of the proposed approach. While linear transformation-based methods excel in computation and memory efficiency, there is still a substantial performance gap against modular-based methods, such as Flamingo and BLIP-2. We attribute such gap to a lot of trainable parameters in th', 'high', 'paper_018_openreview_2024_02_11_sec_5', NULL, FALSE)
ON CONFLICT DO NOTHING;

