INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_019_ev_001', 'assessment_ai_paper_019_openreview_2024_02_11', 'paper_019_openreview_2024_02_11_chunk_0001', NULL, 1, NULL, 'text', 'paper_019_openreview_2024_02_11_chunk_0001', 'quote', 'The rapid development of Large Language Models (LLMs) has substantially expanded the range of tasks they can address. In the field of Natural Language Processing (NLP), researchers have shifted their focus from conventional NLP tasks (e.g., sequence tagging and parsing) towards tasks that revolve around aligning with human needs (e.g., brainstorming and email writing). This shift in task distribution imposes new requirements on evaluating these aligned models regarding generality (i.e., assessing performance across diverse scenarios), flexibility (i.e., examining under different protocols), and interpretability (i.e., scrutinizing models with explanations). In this paper, we propose a generative judge with 13B parameters, A UTO -J, designed to address these challenges. Our model is trained on user queries and LLM-generated responses under massive real-world scenarios and accommodates div', 'high', 'paper_019_openreview_2024_02_11_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_019_ev_002', 'assessment_ai_paper_019_openreview_2024_02_11', 'paper_019_openreview_2024_02_11_chunk_0046', NULL, 28, NULL, 'text', 'paper_019_openreview_2024_02_11_chunk_0046', 'quote', 'Query MyEx,towhomIwasnevermarried,justservedmewithdivorcepapersTLDR-I’mintheprocessofevictingmyexfrommyhousein Kansas. Hejustservedmewithdivorcepapers,thoughwewerenevermarried. He’sclaimingitwas"commonlaw"andIthinkhe’strying togetmyhouse. ThisisjustsostrangethatIfeellikeI’mlivinginanotheruniverse. IhopeIcangetalittleadvice. Thisisallhappeningin Kansas. Anyway,myexandIweretogetherforabout10years. Almost8yearsagoIboughtahouse. Iboughtthehouse. Me. Alone. My downpayment,mycredit,mymortgage. Hedidn’tpayanything. Hisnamewasneveronanything. Notthetitle,nottheinsurance,notthe mortgage,noteventheutilities. Wedidhaveanunwrittenagreementthathe’dpayhalfthemortgage,utilities,andothersharedexpenses likegroceries. Andforaboutayear,maybe,hedidpaymevaryingamountsofmoney. Itwasneverhalf,anditcausedalotofarguments. Whateverhepaidme,hepaidincash. Sincesummer2011Ihavepaidallofit. Hepaysforwhateverfoodheeats', 'high', 'paper_019_openreview_2024_02_11_sec_g', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
