VALUES ('paper_020_ev_003', 'assessment_ai_paper_020_openreview_2024_02_11', 'paper_020_openreview_2024_02_11_chunk_0000', NULL, 1, NULL, 'text', 'paper_020_openreview_2024_02_11_chunk_0000', 'quote', 'R ETHINKING AND E XTENDING THE P ROBABILISTIC I NFERENCE C APACITY OF GNN S

