INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_022_ev_001', 'assessment_ai_paper_022_openreview_2024_02_11', 'paper_022_openreview_2024_02_11_chunk_0001', NULL, 1, NULL, 'text', 'paper_022_openreview_2024_02_11_chunk_0001', 'quote', 'Understanding the interactions and interplay of microorganisms is a great challenge with many applications in medical and environmental settings. In this work, we model bacterial communities directly from their genomes using graph neural networks (GNNs). GNNs leverage the inductive bias induced by the set nature of bacteria, enforcing permutation equivariance and granting combinatorial generalization. We propose to learn the dynamics implicitly by directly predicting community relative abundance profiles at steady state, thus escaping the need for growth curves. On two real-world datasets, we show for the first time generalization to unseen bacteria and different community structures. To investigate the prediction results more deeply, we create a simulation for flexible data generation and analyze effects of bacteria interaction strength, community size, and training data amount.', 'high', 'paper_022_openreview_2024_02_11_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_022_ev_002', 'assessment_ai_paper_022_openreview_2024_02_11', 'paper_022_openreview_2024_02_11_chunk_0019', NULL, 9, NULL, 'text', 'paper_022_openreview_2024_02_11_chunk_0019', 'quote', 'Our work sets the stage for the application of GNNs to microbial communities. These models can implicitly learn growth dynamics, and empirically outperform MLPs in terms of accuracy and generalization. Empirically, they outperform MLPs in terms of accuracy and generalization capabilities. Altogether, GNNs hold great potential for further applications. Furthermore, our results show that genomes are sufficient to learn an accurate model that can generalize predictions beyond observed communities. To our knowledge, this is the first attempt at predicting microbial community profiles from genomes directly. Recently, Lam et al. (2020) employed genome-scale metabolic models (GEMs) (van den Berg et al., 2022) adapted for microbial communities (Machado et al., 2018) to predict pairwise bacterial interactions. Hence, a potential next step would be to apply GNNs to such GEMs. Finally, our simulati', 'high', 'paper_022_openreview_2024_02_11_sec_4', NULL, FALSE)
