INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_025_openreview_2024_02_11_descriptor_001', 'paper_025_openreview_2024_02_11', 'research_problem', 'problem_statement', 'We study data distillation for auto-regressive machine learning tasks, where the input and output have a strict left-to-right causal structure. More specifically, we propose Farzi, which summarizes an event sequence dataset into a small number of synthetic sequences — Farzi Data — which are optimized to maintain (if not improve) model performance compared to training on the full dataset.', 'paper_025_openreview_2024_02_11_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

