INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_026_openreview_2024_02_11_chunk_0000', 'paper_026_openreview_2024_02_11', 'paper_026_openreview_2024_02_11_sec_front_matter', 0, 0, 1, 1, 'body_text', 'BATTLE: T OWARDS B EHAVIOR - ORIENTED A DVER - SARIAL A TTACKS AGAINST D EEP R EINFORCEMENT L EARNING

Anonymous authors Paper under double-blind review', 34, 152, 'high')
