VALUES ('paper_027_openreview_2024_02_11_chunk_0010', 'paper_027_openreview_2024_02_11', 'paper_027_openreview_2024_02_11_sec_4_1', 10, 1, 7, 7, 'body_text', 'Model Name Complexity Faithfulness Diversity Conformity Performance Real data 0 . 145 0 . 855 0 . 466 0 . 963 0 . 855 L LAMA -7B 0 . 235 0 . 708 0 . 439 0 . 357 0 . 749 L LAMA -2-7B 0 . 238 0 . 714 0 . 449 0 . 440 0 . 754 V ICUNA -7B 0 . 113 0 . 815 0 . 365 0 . 222 0 . 744 L LAMA -2-C HAT -7B 0 . 065 0 . 860 0 . 334 0 . 173 0 . 749', 127, 333, 'high')
