INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_028_openreview_2024_02_11_descriptor_001', 'paper_028_openreview_2024_02_11', 'research_problem', 'problem_statement', 'With the emergence of generative conversational large language models (LLMs) like ChatGPT, serving as virtual assistants in various fields, the stability and reliability of their responses have become crucial. However, during usage, it has been observed that these models tend to waver in their judgements when confronted with follow-up questions from users expressing skepticism or disagreement.', 'paper_028_openreview_2024_02_11_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

