VALUES ('paper_029_ev_004', 'assessment_ai_paper_029_openreview_2024_02_11', 'paper_029_openreview_2024_02_11_chunk_0000', NULL, 1, NULL, 'text', 'paper_029_openreview_2024_02_11_chunk_0000', 'quote', 'D O C URRENT L ARGE L ANGUAGE M ODELS M ASTER A DEQUATE C LINICAL K NOWLEDGE ?

