VALUES ('paper_030_ev_004', 'assessment_ai_paper_030_openreview_2024_02_11', 'paper_030_openreview_2024_02_11_chunk_0012', NULL, 7, NULL, 'text', 'paper_030_openreview_2024_02_11_chunk_0012', 'quote', 'To evaluate the performance of the proposed framework,we performed it on both FJSP instance of random synthesis and publicly available FJSP benchmarks.', 'high', 'paper_030_openreview_2024_02_11_sec_5', NULL, FALSE)
