INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_031_iclr_2026_proceedings_chunk_0022', 'paper_031_iclr_2026_proceedings', 'paper_031_iclr_2026_proceedings_sec_a', 22, 0, 15, 15, 'body_text', 'In this work, large language models (LLMs) are used exclusively for polishing the writing and checking grammar. They are not involved in research ideation, experimental design, data analysis, or the formulation of conclusions. The authors make all substantive intellectual contributions.', 52, 287, 'high')
