INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_031_iclr_2026_proceedings_chunk_0030', 'paper_031_iclr_2026_proceedings', 'paper_031_iclr_2026_proceedings_sec_d_4', 30, 0, 19, 19, 'body_text', 'We quantify the invocation rate and recovery capability of the CAE’s rollback mechanism across three benchmarks. Consistent with the protocol in Sec.2.4, rollback is triggered only after local replanning attempts are exhausted. Table 5 reveals that while rollbacks occur in 12–19% of episodes, they are highly effective: approximately 70% of these episodes eventually succeed. Notably, full restarts are required in less than 3% of cases. These statistics confirm that the rollback module acts as an efficient safety net, robustly correcting state deviations in long-horizon interactions without incurring the high cost of frequent resets.', 121, 639, 'high')
ON CONFLICT DO NOTHING;

INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_031_iclr_2026_proceedings_chunk_0031', 'paper_031_iclr_2026_proceedings', 'paper_031_iclr_2026_proceedings_sec_d_5', 31, 0, 19, 20, 'body_text', 'We evaluate the transferability of LongHorizonUI to AndroidWorld and OSWorld under a strict zero-shot protocol. We deploy the core pipeline (MEP, DRD, CAE) without any parameter updates

