VALUES ('paper_031_iclr_2026_proceedings_descriptor_002', 'paper_031_iclr_2026_proceedings', 'contributions', 'claimed_contribution', 'Although agents based on multimodal large language models (MLLMs) demonstrate proficiency in general short-term graphical user interface (GUI) tasks, their robustness remains a significant challenge for handling complex long-horizon tasks in dynamic environments . In response, the LongHorizonUI framework is proposed to improve the sustained reliability of agents in long-horizon GUI tasks. To overcome core limitations, we establish a comprehensive long-horizon benchmark, LongGUIBench, covering multiple categories of games and complex general applications, with long-horizon tasks defined as requiring more than 15 steps for rigorous evaluation o', 'paper_031_iclr_2026_proceedings_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_031_iclr_2026_proceedings_descriptor_003', 'paper_031_iclr_2026_proceedings', 'claims', 'major_claim', 'While multimodal large language models (MLLMs) have shown promise in short-horizon GUI agents, their performance degrades significantly on longhorizon tasks involving complex, dynamic interfaces. To address this, we present LongHorizonUI, a framework designed to enhance the reliability and robustness of MLLM-based agents in extended interactive environments. Moreover, we establish a new long-horizon benchmark, named', 'paper_031_iclr_2026_proceedings_chunk_0013', NULL, 'medium')
ON CONFLICT DO NOTHING;

