INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_031_ev_005', 'assessment_ai_paper_031_iclr_2026_proceedings', 'paper_031_iclr_2026_proceedings_chunk_0004', NULL, 3, NULL, 'text', 'paper_031_iclr_2026_proceedings_chunk_0004', 'quote', 'In this section, as outlined in Figure 3, we introduce LongHorizonUI, a framework dedicated to long-horizon reasoning for GUI agents. Building upon the LongGUIBench benchmark spanning complex games and general application workflows, our approach integrates three core components: (i) a Multimodal Enhanced Perceiver integrating OCR and icon detection, (ii) a Deep Reflection Decider enabling action verification and adaptive planning, and (iii) a Compensatory Action Executor ensuring robust action execution. The following sections detail each element. The discussion of related work is in the Appendix C due to the page limit.', 'high', 'paper_031_iclr_2026_proceedings_sec_2', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_031_ev_006', 'assessment_ai_paper_031_iclr_2026_proceedings', 'paper_031_iclr_2026_proceedings_chunk_0011', NULL, 7, NULL, 'text', 'paper_031_iclr_2026_proceedings_chunk_0011', 'quote', 'To ensure fair evaluation across benchmarks, we select base models aligned with their architectures and configure consistent experimental settings. For LongHorizonBench, we adopt a representative MLLMs (Comanici et al., 2025) as the backbone to ensure stable reasoning in long-horizon tasks. All components operate without fine-tuning, leveraging pre-trained models for task execution and evaluation. Task-specific prompts are designed to prevent ambiguity and enhance reproducibility (see Appendix D.1 for more details.).', 'high', 'paper_031_iclr_2026_proceedings_sec_3_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_031_ev_007', 'assessment_ai_paper_031_iclr_2026_proceedings', 'paper_031_iclr_2026_proceedings_chunk_0003', NULL, 2, NULL, 'text', 'paper_031_iclr_2026_proceedings_chunk_0003', 'quote', 'OurSolution. Inthiswork,weproposeLongHorizonUI,aframeworkforenhancingtherobustness of MLLM-based GUI agents in complex and long-horizon tasks, as shown in Figure 1. Specifically, first, we propose a Multimodal Enhanced Perceiver (MEP) that integrates object detection and OCR outputs to capture rich contextual information, assigning indices to UI elements for temporally consistent state representation. Then, we design a Deep Reflection Decider (DRD) that performs structured, multi-level reasoning through formatted prompts, enforcing explicit validation of historical coherence, goal relevance, and action justification to ensure the decision fidelity. Finally, we incorporate a Compensatory Action Executor (CAE) that implements a multi-level fallback strategy by leveraging the element indices, relative layout priors, and absolute screen coordinates. Concurrently, a real-time progress monitor', 'high', 'paper_031_iclr_2026_proceedings_sec_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_031_ev_008', 'assessment_ai_paper_031_iclr_2026_proceedings', 'paper_031_iclr_2026_proceedings_chunk_0026', NULL, 17, NULL, 'text', 'paper_031_iclr_2026_proceedings_chunk_0026', 'quote', 'We adopt Googles Gemini-2.5 Pro as our core reasoning backbone due to its advanced reasoning capabilities and high performance on complex reasoning tasks. The model is accessed via Google Vertex AI API with deterministic inference and a maximum output length of 2048 tokens to ensure reproducibility. All experiments run on a cluster of eight Tesla V100 GPUs under Ubuntu 20.04 LTS, using PyTorch 2.1 and CUDA 11.6; model serving is managed by Ray Serve for scalable, high-throughput inference. Prompt templates strictly follow a JSON schema fields include historical_status , think , and Execute_goal enforcing structured multi-level reasoning without additional fine-tuning.', 'high', 'paper_031_iclr_2026_proceedings_sec_d_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_031_ev_009', 'assessment_ai_paper_031_iclr_2026_proceedings', 'paper_031_iclr_2026_proceedings_chunk_0007', NULL, 4, NULL, 'text', 'paper_031_iclr_2026_proceedings_chunk_0007', 'quote', 'Accurately identifying and disambiguating interactive elements in context is key to enabling task automation in complex GUIs. To this end, we propose the Multimodal Enhanced Perceiver (MEP), which unifies icon detection, OCR recognition, and heuristic repair into an ID-centred abstraction layer, extracting actionable signals from evolving GUIs, inspired by prior work (Lu et al., 2024c). Specifically, given a GUI screenshot S , MEP extracts visual elements through parallel perception modules: (i) An enhanced detector identifies interactive controls, producing E = ( id ,b ,c ) N , ui i i i i =1 with id a unique spatial tag, b its bounding box, and c the confidence from the detector head i i i (sigmoid class probability). IDs serve as stable anchors, robust to small layout variations. MEP also highlightspreviouslyclickedelements.(ii)AconventionalOCRmoduleextracts E = ( t ,b ) M , text j j j', 'high', 'paper_031_iclr_2026_proceedings_sec_2_2', NULL, FALSE)
ON CONFLICT DO NOTHING;

