INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_032_iclr_2026_proceedings_chunk_0027', 'paper_032_iclr_2026_proceedings', 'paper_032_iclr_2026_proceedings_sec_d', 27, 0, 17, 17, 'body_text', 'Large Language Models (LLMs) were used solely as a general-purpose writing aid in the preparation of this paper. Specifically, they were used to help polish grammar and improve the clarity of certain sentences. No LLMs were used for research ideation, experimental design, data analysis, or drawing conclusions. All substantive contributions to the research and writing were made by the authors.', 78, 395, 'high')
ON CONFLICT DO NOTHING;

