INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_033_ev_004', 'assessment_ai_paper_033_iclr_2026_proceedings', 'paper_033_iclr_2026_proceedings_chunk_0016', NULL, 9, NULL, 'text', 'paper_033_iclr_2026_proceedings_chunk_0016', 'quote', 'Various metrics have been proposed to quantify deviations from perfect calibration, including ECE (Guo et al., 2017; Rahaman et al., 2021; Minderer et al., 2021). The binning ECE has been widely used to estimate the conditional expectation E [ Y | f ( X )] in the ECE, which partitions the probability interval into discrete bins. Despite its popularity, binning ECE is sensitive to hyperparameters such as the number of bins, and it lacks both consistency and smoothness as a distance metric (Kumar et al., 2019; Nixon et al., 2019; Minderer et al., 2021). A broader comparison of ECE variants is given by Gruber & Buettner (2022). Błasiok et al. (2023) systematically studied calibration distances and formalized the true distance from calibration as a rigorous notion of deviation from perfect calibration. As an efficiently estimable surrogate, they proposed the smooth CE, building on Foster & H', 'high', 'paper_033_iclr_2026_proceedings_sec_5', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_033_ev_005', 'assessment_ai_paper_033_iclr_2026_proceedings', 'paper_033_iclr_2026_proceedings_chunk_0002', NULL, 1, NULL, 'text', 'paper_033_iclr_2026_proceedings_chunk_0002', 'quote', 'Probabilistic prediction plays a central role in many real-world applications, such as healthcare (Jiang et al., 2012), weather forecasting (Murphy & Winkler, 1984), and language modeling (Nguyen & O’Connor, 2015), where uncertainty estimates are often critical. Since ensuring the reliability of such predictions has become a key challenge in modern machine learning, calibration Dawid (1982); Foster & Vohra (1998)—which requires that predicted probabilities align with the actual frequency of the true label—has attracted increasing attention. Calibration is a relatively weak condition that can be satisfied by simple models. However, it is frequently violated in practice. Notably, Guo et al. (2017) demonstrated that many modern deep learning models can be significantly miscalibrated, which has since drawn increasing attention to calibration within the machine learning community. Although va', 'high', 'paper_033_iclr_2026_proceedings_sec_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_033_ev_006', 'assessment_ai_paper_033_iclr_2026_proceedings', 'paper_033_iclr_2026_proceedings_chunk_0061', NULL, 50, NULL, 'text', 'paper_033_iclr_2026_proceedings_chunk_0061', 'quote', 'We conducted similar experiments using a two-layer neural network corresponding to Section 4.3. We prepared the toy dataset and designed the two-layer neural network to satisfy Assumption 1 in Appendix H. We used the sigmoid activation function, initialized the parameters independently from the standard Gaussian distribution, and set the number of hidden units to be even to satisfy Assumption (A3). The coefficients a were also set according to the specification in Assumption r (A3). Unless otherwise stated, we used 300 hidden units. We used full-batch gradient descent (GD) for optimization with a fixed step size of w = 0 . 01 . First, we performed experiments on the same toy dataset used for GBTs. We evaluated the training and test metrics by increasing the number of GD iterations while fixing the training dataset size ( n = 200 ). Figure 4(a) reports the same set of metrics as in the GB', 'high', 'paper_033_iclr_2026_proceedings_sec_k_2', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_033_ev_007', 'assessment_ai_paper_033_iclr_2026_proceedings', 'paper_033_iclr_2026_proceedings_chunk_0059', NULL, 47, NULL, 'text', 'paper_033_iclr_2026_proceedings_chunk_0059', 'quote', 'The results in Section 4 provide concrete guidance for practical training of GBT, / Kernel Boosting / Two-layer NN models. For example, in Section 4.1 (Corollary 2), the first term in the upper bound decreases with the number of iterations T , reflecting the improvement of the training smooth CE. In contrast, the fourth term corresponds to the Rademacher complexity of the tree model and increases with T , reflecting the growth of the generalization gap (i.e., overfitting). The same qualitative behavior appears in Section 4.2 and 4.3. Hence, our analysis formally justifies the following practical tuning rules: i) excessive iterations can worsen smooth CE due to overfitting and ii) appropriate early stopping (and regularization) can jointly optimize accuracy and smooth CE. This shows that, from the perspective of calibration as well, controlling hypothesis class complexity via regularizati', 'high', 'paper_033_iclr_2026_proceedings_sec_j_4', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_033_ev_008', 'assessment_ai_paper_033_iclr_2026_proceedings', 'paper_033_iclr_2026_proceedings_chunk_0003', NULL, 2, NULL, 'text', 'paper_033_iclr_2026_proceedings_chunk_0003', 'quote', 'potential improvement of the loss function achievable by applying Lipschitz-continuous transformations to the model outputs. This framework provides an optimization-theoretic perspective on calibration. Nevertheless, analyses based on this concept typically assume access to infinite data (i.e., population-level risk) (Błasiok et al., 2023; Globus-Harris et al., 2023), which limits their applicability to real-world algorithms based on finite training samples. Furthermore, only a few theoretical results explicitly connect calibration error with concrete learning algorithms (Hansen et al., 2024; Błasiok et al., 2023). As a result, a key question remains unresolved: What types of learning algorithms can achieve both high predictive accuracy and strong calibration guarantees in practice? To address this gap, we focus on the smooth calibration error (CE) (Błasiok et al., 2023; Foster & Hart, 2', 'high', 'paper_033_iclr_2026_proceedings_sec_1', NULL, FALSE)
