INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_034_ev_001', 'assessment_ai_paper_034_iclr_2026_proceedings', 'paper_034_iclr_2026_proceedings_chunk_0001', NULL, 1, NULL, 'text', 'paper_034_iclr_2026_proceedings_chunk_0001', 'quote', 'Identifying the extent to which every temporal segment influences a model’s predictions is essential for explaining model decisions and increasing transparency. While post-hoc explainable methods based on gradients and feature-based attributions have been popular, they suffer from reference state sensitivity and struggle to generalize across time-series datasets, as they treat time points independently and ignore sequential dependencies. Another perspective on explainable timeseries classification is through interpretable components of the model, for instance, leveraging self-attention mechanisms to estimate temporal attribution; however, recent findings indicate that these attention weights often fail to provide faithful measures of temporal importance. In this work, we advance this perspective and present a novel explainability-driven deep learning framework, TimeSliver , which jointly', 'high', 'paper_034_iclr_2026_proceedings_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_034_ev_002', 'assessment_ai_paper_034_iclr_2026_proceedings', 'paper_034_iclr_2026_proceedings_chunk_0020', NULL, 10, NULL, 'text', 'paper_034_iclr_2026_proceedings_chunk_0020', 'quote', 'In this work, we presented TimeSliver —a novel deep learning framework that linearly combines raw time series with their symbolic counterparts to construct a global representation facilitating temporal attribution calculation. Our importance scores offer insights into positively and negatively influencing time segments. The effectiveness of TimeSliver is demonstrated by its average improvement of 11% over the best baselines across seven diverse datasets, spanning real-world and synthetic, univariate and multivariate time series with varied temporal dynamics, while maintaining high predictive performance. In the future, it will be interesting to consider human-in-the-loop expert validation (for tasks like sleep-stage classification using EEG) to harness TimeSliver ’s explainability for practical applications. Additionally, TimeSliver ’s principles can be extended to provide feature attrib', 'high', 'paper_034_iclr_2026_proceedings_sec_4', NULL, FALSE)
