INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_035_iclr_2026_proceedings_chunk_0041', 'paper_035_iclr_2026_proceedings', 'paper_035_iclr_2026_proceedings_sec_d_1_3', 41, 0, 24, 24, 'body_text', 'For all datasets and tasks, we use the AdamW optimizer Loshchilov & Hutter (2019). We experimented with two learning rate schedulers (see Table 6): “Reduce On Plateau” and “Cosine Annealing with Warmup”, where warmup spanned 10% of the total training steps. The scheduler yielding the best validation performance was selected.', 65, 326, 'high')
