INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_035_iclr_2026_proceedings_chunk_0047', 'paper_035_iclr_2026_proceedings', 'paper_035_iclr_2026_proceedings_sec_f', 49, 0, 27, 27, 'body_text', 'We employed large language models (LLMs) to support the writing process, specifically for improving clarity in technical explanations, refining grammar and style, and enhancing overall readability. LLMs werealsousedtoalimitedextenttoaidtheprocessoffindingrelatedworks. Allresearchcontributions, including the design of experiments, data analysis, and conclusions, are entirely our own. The LLMs were used strictly as writing aids to improve presentation quality, not for generating research content or shaping the substance of our work.', 86, 536, 'high')
ON CONFLICT DO NOTHING;

INSERT INTO paper_elements (element_id, paper_version_id, section_id, element_type, label, caption, page_number, extracted_text, asset_object_key, parse_quality)
VALUES ('paper_035_iclr_2026_proceedings_figure_1', 'paper_035_iclr_2026_proceedings', 'paper_035_iclr_2026_proceedings_sec_2', 'figure', 'Figure 1', 'Overview of CHARM . We extract attention and activation matrices from LLM computations and build an attributed graph from them: edges and their features are derived from off-diagonal attention scores; node features are based on activations, and diagonal attention values. The resulting graph is processed by a GNN-based architecture, which outputs either token-level hallucination scores (as illustrated) or a global hallucination score for the entire sentence.', 2, NULL, 'renders/paper_035/iclr_2026_proceedings/page-0002.png', 'good')
ON CONFLICT DO NOTHING;

INSERT INTO paper_elements (element_id, paper_version_id, section_id, element_type, label, caption, page_number, extracted_text, asset_object_key, parse_quality)
VALUES ('paper_035_iclr_2026_proceedings_figure_2', 'paper_035_iclr_2026_proceedings', 'paper_035_iclr_2026_proceedings_sec_4_2', 'figure', 'Figure 2', 'HD with CHARM . The input is an attributed graph (shown in the bottom left). First f mp obtains refined node / token representations via msg-passing. Next, f aggregates these if response pool level predictions are required. Finally, a projection head, f , outputs the detection score.', 5, NULL, 'renders/paper_035/iclr_2026_proceedings/page-0005.png', 'good')
ON CONFLICT DO NOTHING;

