INSERT INTO papers (paper_id, title, authors, authors_status, language, arxiv_id, openreview_forum_id, venue, publication_year, abstract, doi)
VALUES ('paper_036', 'Benefits and Pitfalls of Reinforcement Learning for Language Model Planning: A Theoretical Perspective', '["Wang, Siwei", "Shen, Yifei", "Sun, Haoran", "Feng, Shi", "Teng, Shang-Hua", "Dong, Li", "Hao, Yaru", "Chen, Wei"]'::jsonb, 'verified', 'en', NULL, NULL, 'ICLR', 2026, 'Recent reinforcement learning (RL) methods have substantially enhanced the planning capabilities of Large Language Models (LLMs), yet the theoretical basis for their effectiveness remains elusive. In this work, we investigate RL''s benefits and limitations through a tractable graph-based abstraction, focusing on policy gradient (PG) and Q-learning methods. Our theoretical analyses reveal that supervised fine-tuning (SFT) may introduce co-occurrence-based spurious solutions, whereas RL achieves correct planning primarily through exploration, underscoring exploration’s role in enabling better generalization. However, we also show that PG suffers from diversity collapse, where output diversity decreases during training and persists even after perfect accuracy is attained. By contrast, Q-learning provides two key advantages: off-policy learning and diversity preservation at convergence. We further demonstrate that careful reward design is necessary to prevent Q-value bias in Q-learning. Finally, applying our framework to the real-world planning benchmark Blocksworld, we confirm that these behaviors manifest in practice.', NULL)
ON CONFLICT DO NOTHING;

