VALUES ('paper_037_ev_007', 'assessment_ai_paper_037_iclr_2026_proceedings', 'paper_037_iclr_2026_proceedings_chunk_0023', NULL, 12, NULL, 'text', 'paper_037_iclr_2026_proceedings_chunk_0023', 'quote', 'The garage contributors. Garage: A toolkit for reproducible reinforcement learning research. https://github.com/rlworkgroup/garage , 2019.

