INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_039_ev_001', 'assessment_ai_paper_039_iclr_2026_proceedings', 'paper_039_iclr_2026_proceedings_chunk_0001', NULL, 1, NULL, 'text', 'paper_039_iclr_2026_proceedings_chunk_0001', 'quote', 'Graphon models have emerged as powerful tools for modeling complex network structures by capturing connection probabilities among nodes. A key challenge in their application lies in accurately characterizing the graphon function, particularly with respect to parameters that govern its smoothness, which significantly impact the estimation accuracy. In this article, we propose a novel graphon crossvalidation method for selecting tuning parameters and estimation approaches. Our method is both theoretically sound and computationally efficient. We show that our proposed cross-validation score is asymptotically parallel to the estimation error, and the selected model asymptotically converges to the optimal model. Through extensive simulations and real-world applications, we demonstrate that our method consistently delivers superior computational efficiency and accuracy.', 'high', 'paper_039_iclr_2026_proceedings_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_039_ev_002', 'assessment_ai_paper_039_iclr_2026_proceedings', 'paper_039_iclr_2026_proceedings_chunk_0014', NULL, 10, NULL, 'text', 'paper_039_iclr_2026_proceedings_chunk_0014', 'quote', 'Our proposed method, denoted as CV-imputation, offers several key advantages that make it a valuable tool for analyzing network data. Firstly, CV-imputation is versatile as it does not assume any specific form for the graphon function, making it broadly applicable across different types of networks. This flexibility enables researchers to apply CV-imputation to various network structures without conforming to a specific model. Moreover, CV-imputation is supported by rigorous theoretical foundations, showing that the minimizer of CV-imputation asymptotically converges to the minimizer of the mean squared error (MSE) in our model. This theoretical basis enhances confidence in the accuracy and consistency of CV-imputation results. In terms of computation efficiency, CV-imputation outperforms existing methods by eliminating costly singular value decomposition (SVD) steps, making it particula', 'high', 'paper_039_iclr_2026_proceedings_sec_7', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_039_ev_003', 'assessment_ai_paper_039_iclr_2026_proceedings', 'paper_039_iclr_2026_proceedings_chunk_0007', NULL, 4, NULL, 'text', 'paper_039_iclr_2026_proceedings_chunk_0007', 'quote', 'A set of potential graphon estimates is denoted by P ˆ ( M A ) , where M . The CV-imputation | ↗ M score is crafted to fine-tune M to select the best estimate from this set. In this section, we offer asymptotic justifications for the CV-imputation score. We aim to demonstrate that V ( M ) approximates L ( M ) uniformly up to a constant by postulating K assumptions on the maximum K -fold optimism bias: 1 2 Q ( M ) = sup P ˆ ( M A ) P ˆ ( M ) , K k n ( n 1) | ↘ F 1 k K ↔ ↔ ↘ # # # # where denotes the Frobenius norm. The optimism # bias quantifies the # maximum prediction bias F ≃ · ≃ between the full-sample estimate and the estimate obtained after data splitting and imputation. Then, under the following conditions: Condition 1. There exists a positive constant ε > 0 such that for any M and any ϑ > 0 , there ↗ M exist a constant ϖ and an integer K such that 0 0 Q ( M ) K P ϖ ϑ K K , ω 0 0 K', 'high', 'paper_039_iclr_2026_proceedings_sec_4', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_039_ev_004', 'assessment_ai_paper_039_iclr_2026_proceedings', 'paper_039_iclr_2026_proceedings_chunk_0002', NULL, 1, NULL, 'text', 'paper_039_iclr_2026_proceedings_chunk_0002', 'quote', 'Graphon models represent cutting-edge statistical and machine-learning techniques for describing intricate network structures. In these models, the presence of an edge between nodes i and j hinges on a probability, independently determined by a measurable symmetric graphon function f across the unit square (Lovász and Szegedy, 2006). The graphon function f , the key to the model, gauges the probability of node connections. Accurately estimating f poses a significant challenge to the models’ general application. The efficacy of existing estimation methods is intrinsically linked to the precise calibration of tuning parameters. For instance, the accuracy of the graphon function estimated using the sort-and-smoothing (SAS) method (Chan and Airoldi, 2014) or the neighborhood-smoothing (NS) method (Zhang et al., 2017) is heavily contingent on the chosen size of the neighborhood. This paramete', 'high', 'paper_039_iclr_2026_proceedings_sec_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

