INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_040_iclr_2026_proceedings_chunk_0028', 'paper_040_iclr_2026_proceedings', 'paper_040_iclr_2026_proceedings_sec_a_1', 28, 0, 14, 14, 'body_text', 'Large language models were utilized solely for minor linguistic improvements, including enhanced phrasing and clarity. These tools played no role in content generation, experimental design, data analysis, or interpretation. The authors are entirely responsible for all ideas, results, and conclusions presented in this paper.', 57, 325, 'high')
