INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_041_ev_001', 'assessment_ai_paper_041_iclr_2026_proceedings', 'paper_041_iclr_2026_proceedings_chunk_0001', NULL, 1, NULL, 'text', 'paper_041_iclr_2026_proceedings_chunk_0001', 'quote', 'Real-world settings where language models (LMs) are deployed — in domains spanninghealthcare,finance,andotherformsofknowledgework—requiremodels tograpple withincompleteinformation andreasonunder uncertainty. Yet mostLM evaluationsfocusonproblems withwell-definedanswersand successcriteria. This gap exists in part because natural problems involving uncertainty are difficult to construct: given that LMs have access to most of the same knowledge as humans, it is non-trivial to design questions for which LMs will struggle to produce correct answers. As a result, LM performance on reasoning under uncertainty remains poorly characterized. To address this gap, we introduce O PEN E STIMATE , an extensible,multi-domainbenchmarkforevaluatingLMsonprobabilisticestimation tasks that require models to synthesize knowledge from pretraining and express predictionsas Bayesianpriors. We assessthesepriorsfo', 'high', 'paper_041_iclr_2026_proceedings_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_041_ev_002', 'assessment_ai_paper_041_iclr_2026_proceedings', 'paper_041_iclr_2026_proceedings_chunk_0018', NULL, 10, NULL, 'text', 'paper_041_iclr_2026_proceedings_chunk_0018', 'quote', 'While O PEN E STIMATE provides a first step toward evaluating uncertainty in open-domain estimation, several limitations remain that point to directions for future work. Ground truth values in O PEN E S - TIMATE were estimated from finite samples, and therefore mightexhibit estimation error. Moreover, while O PEN E STIMATE was constructed to reduce systematic information leakage, leakage still can occur to varying degrees. In terms of scope, the current benchmark is limited to questions derived fromthreedatasetsacrossthreedomains;expandingtonewdomainswouldleadtoamorethorough evaluation of priors. In terms of evaluation, we focus our attention on zero-shot methods without retrieval or fine-tuning; studying training-time interventions for uncertainty awareness and domain adaptationwouldbeacomplementarynextstepinfuturework.', 'high', 'paper_041_iclr_2026_proceedings_sec_5', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_041_ev_003', 'assessment_ai_paper_041_iclr_2026_proceedings', 'paper_041_iclr_2026_proceedings_chunk_0015', NULL, 8, NULL, 'text', 'paper_041_iclr_2026_proceedings_chunk_0015', 'quote', 'We investigate how inference-timesettings influence the qualityof elicited priors, focusing onthree factors: (i) temperature or reasoning effort, (ii) system prompt, and (iii) elicitation protocol. To isolatetheireffects,weevaluatebothareasoningmodel(OpenAIo4-mini)andanon-reasoningmodel (OpenAI gpt-4o). The full set of results is shown in Appendix A.2. None of the settings tested has aconsequential impactonperformance, indicatingthat moresophisticatedapproaches toimproving accuracyandcalibrationareneeded.', 'high', 'paper_041_iclr_2026_proceedings_sec_3_2', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_041_ev_004', 'assessment_ai_paper_041_iclr_2026_proceedings', 'paper_041_iclr_2026_proceedings_chunk_0016', NULL, 8, NULL, 'text', 'paper_041_iclr_2026_proceedings_chunk_0016', 'quote', 'Our work intersects with three major lines of language model research: evaluating probabilistic reasoning as a mathematical skill, structuring probabilistic reasoning for better estimation, and applicationstoforecasting.

