INSERT INTO paper_elements (element_id, paper_version_id, section_id, element_type, label, caption, page_number, extracted_text, asset_object_key, parse_quality)
VALUES ('paper_042_iclr_2026_proceedings_figure_1', 'paper_042_iclr_2026_proceedings', 'paper_042_iclr_2026_proceedings_sec_2', 'figure', 'Figure 1', 'Ctrl-World is designed for policy-in-the-loop rollouts with generalist robot policies. It generates joint multi-view predictions (including wrist views), enforces fine-grained action control via frame-level conditioning, and sustains coherent long-horizon dynamics through pose-conditioned memory retrieval. These components enable (1) accurate policy evaluation in imagination, with alignment to real-world rollouts, and (2) targeted policy improvement through synthetic trajectories.', 2, NULL, 'renders/paper_042/iclr_2026_proceedings/page-0002.png', 'good')
ON CONFLICT DO NOTHING;

INSERT INTO paper_elements (element_id, paper_version_id, section_id, element_type, label, caption, page_number, extracted_text, asset_object_key, parse_quality)
