INSERT INTO paper_elements (element_id, paper_version_id, section_id, element_type, label, caption, page_number, extracted_text, asset_object_key, parse_quality)
VALUES ('paper_043_iclr_2026_proceedings_table_14', 'paper_043_iclr_2026_proceedings', 'paper_043_iclr_2026_proceedings_sec_l_3', 'table', 'Table 14', 'Evaluation of CS on the Adult (sex) as the sensitive attribute. control provided by CS translates into more balanced treatment across intersectional groups without sacrificing worst-case utility. M D ISCUSSION : W HEN AND WHY IS CS EXPECTED TO OUTPERFORM OTHER DIVERGENCES ?', 44, '
def calculate_intersectional_metrics(y_pred, y_target, sensitive):
if isinstance(y_pred, torch.Tensor):
y_pred = y_pred.detach().cpu().numpy()
if isinstance(y_target, torch.Tensor):
y_target = y_target.detach().cpu().numpy()
if isinstance(sensitive, torch.Tensor):
sensitive = sensitive.detach().cpu().numpy()

y_pred = y_pred.flatten()
y_target = y_target.flatten()
sensitive = sensitive.flatten()

y_pred_binary = (y_pred > 0.5).astype(int)

groups = [0, 1, 2, 3]

rates = {}
for g in groups:
mask = sensitive == g
if mask.sum() > 0:
rates[g] = y_pred_binary[mask].mean()', 'renders/paper_043/iclr_2026_proceedings/page-0044.png', 'good')
