INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_044_iclr_2026_proceedings_chunk_0032', 'paper_044_iclr_2026_proceedings', 'paper_044_iclr_2026_proceedings_sec_a_1', 32, 0, 16, 16, 'body_text', 'We employ Image-based nearest neighbor distances inspired by Gadre et al. (2023). Following the DataComp methodology, we use embeddings from OpenAI’s pretrained CLIP ViT-L/14 model (Radford et al., 2021) to compute the image representations ϕ ( · ) . For each pool sample x ∈ D , the i curation score is computed as the maximum cosine similarity to any target sample in T , i.e., the pool sample is scored based on its closest (most similar) target sample. This nearest-neighbor mechanism creates a deterministic relationship where each pool sample’s score is determined by exactly one target sample.', 127, 600, 'high')
ON CONFLICT DO NOTHING;

INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
