INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
VALUES ('paper_044_iclr_2026_proceedings_chunk_0052', 'paper_044_iclr_2026_proceedings', 'paper_044_iclr_2026_proceedings_sec_c_7', 52, 0, 28, 28, 'body_text', 'For Image-based curation, we manage to find canaries that will reliably leak their presence in the shaders21k dataset. For TRAK , our canaries achieve similar success rates as the original attack on the final trained model. We hypothesize that TRAK’s resistance to canary attacks stems from the limited adversary control. Despite optimizing for maximum signal-to-noise ratio, canaries provide only marginal improvements under a realistic threat scenario. Since the canary gradients are obtain contrastively with thousands of other samples the adversary cannot control, then randomly projected into a lower-dimensional space, and afterwards averaged with all other gradients, it remains challenging to craft a strong signal.', 135, 723, 'high')
ON CONFLICT DO NOTHING;

INSERT INTO paper_text_chunks (chunk_id, paper_version_id, section_id, sequence_index, chunk_index_in_section, page_start, page_end, content_type, text_content, token_count, char_count, location_confidence)
