INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_044_ev_001', 'assessment_ai_paper_044_iclr_2026_proceedings', 'paper_044_iclr_2026_proceedings_chunk_0001', NULL, 1, NULL, 'text', 'paper_044_iclr_2026_proceedings_chunk_0001', 'quote', 'In machine learning, curation is used to select the most valuable data for improving both model accuracy and computational efficiency. Recently, curation has also been explored as a solution for private machine learning: rather than training directly on sensitive data, which is known to leak information through model predictions, the private data is used only to guide the selection of useful public data. The resulting model is then trained solely on curated public data. It is tempting to assume that such a model is privacy-preserving because it has never seen the private data. Yet, we show that without further protection, curation pipelines can still leak private information. Specifically, we introduce novel attacks against popular curation methods, targeting every major step: the computation of curation scores, the selection of the curated subset, and the final trained model. We demonst', 'high', 'paper_044_iclr_2026_proceedings_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_044_ev_002', 'assessment_ai_paper_044_iclr_2026_proceedings', 'paper_044_iclr_2026_proceedings_chunk_0023', NULL, 10, NULL, 'text', 'paper_044_iclr_2026_proceedings_chunk_0023', 'quote', 'Our work demonstrates that data curation pipelines can leak membership information about the target datasets, exposing privacy risks at every stage, from curation scores and curated subset to the final trained model. Image-based nearest-neighbor methods are particularly vulnerable, and even state-of-the-art approaches like TRAK expose privacy risks for small target sets. Our discovered risks become practically relevant when adversaries can introduce manipulated samples in the curation pool, which is the case when the pool is simply crawled from the internet. This highlights that, as curation becomes central to ML, we need novel curation methods with dedicated safeguards, such as Differential Privacy (DP), to reduce potential leakage throughout the entire data curation pipeline.', 'high', 'paper_044_iclr_2026_proceedings_sec_6', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_044_ev_003', 'assessment_ai_paper_044_iclr_2026_proceedings', 'paper_044_iclr_2026_proceedings_chunk_0021', NULL, 10, NULL, 'text', 'paper_044_iclr_2026_proceedings_chunk_0021', 'quote', 'We perform further ablations on various aspects of our curation setups and analyze their impact on the attack success. TRAK We conduct these ablations on attacks against scores, which Image-based yield the strongest leakage signal and thus provide the clear- 2 est insights into the factors affecting attack success. First, we ) % ( analyze the impact of the number of dimensions used for R P Image-based embeddings and TRAK-based gradient projec- F % 1 tions. Our results in Figure 37 suggest that for Image-based 1 @ curation, there is a sweet spot, with the highest leakage at 128 R P dimensions. TRAK requires enough dimensions ( ≥ 1 , 024 ), T 0 below which the attack success drops. Additionally, we show 10 1 10 0 10 1 10 2 10 3 how target dataset size impacts attack success. Our results Privacy Budget ( ) in Figure 32 suggest differences across datasets: e.g., at- Figure 6: Attack success ', 'high', 'paper_044_iclr_2026_proceedings_sec_4_4', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_044_ev_004', 'assessment_ai_paper_044_iclr_2026_proceedings', 'paper_044_iclr_2026_proceedings_chunk_0002', NULL, 1, NULL, 'text', 'paper_044_iclr_2026_proceedings_chunk_0002', 'quote', 'Data curation has become an important part of modern machine learning (ML) pipelines (Maini et al., 2024; Wu et al., 2024), offering a principled way to select high-value data in order to maximize model performance and computational efficiency. By filtering out noisy, low-quality, or redundant samples (Gadre et al., 2023; Li et al., 2024a; Gu et al., 2025; Thrush et al., 2025), curation allows to train on the most informative points, thus improving generalization and resource utilization.

This paradigm is also particularly appealing for sensitive domains, such as finance or healthcare (Schäfer et al., 2024; Assefa et al., 2021), where the available training datasets are usually limited, which hinders the training of powerful ML models. In these settings, curation offers a key advantage: it enables model developers to leverage publicly available data pools and select a subset from these ', 'high', 'paper_044_iclr_2026_proceedings_sec_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

