INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_044_ev_007', 'assessment_ai_paper_044_iclr_2026_proceedings', 'paper_044_iclr_2026_proceedings_chunk_0029', NULL, 14, NULL, 'text', 'paper_044_iclr_2026_proceedings_chunk_0029', 'quote', 'Sung Min Park, Kristian Georgiev, Andrew Ilyas, Guillaume Leclerc, and Aleksander Madry. TRAK: attributing model behavior at scale. In Andreas Krause, Emma Brunskill, Kyunghyun Cho, Barbara Engelhardt, Sivan Sabato, and Jonathan Scarlett (eds.), International Conference on Machine Learning, ICML 2023, 23-29 July 2023, Honolulu, Hawaii, USA , volume 202 of Proceedings of Machine Learning Research , pp. 27074–27113. PMLR, 2023. URL https://proceedings. mlr.press/v202/park23c.html .

