INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_045_iclr_2026_proceedings_descriptor_001', 'paper_045_iclr_2026_proceedings', 'research_problem', 'problem_statement', 'Machine learning systems increasingly face requirements to remove entire domains of information—such as toxic language or biases—rather than individual user data. This task presents a dilemma: full removal of the unwanted domain data is computationally expensive, while random partial removal is statistically inefficient. We find that a domain''s statistical influence is often concentrated in a small subset of its data samples, suggesting a path between ineffective partial removal and unnecessary complete removal. We formalize this as distributional unlearning: a framework to select a small subset that balances forgetting an unwanted distributi', 'paper_045_iclr_2026_proceedings_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

