INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_045_ev_001', 'assessment_ai_paper_045_iclr_2026_proceedings', 'paper_045_iclr_2026_proceedings_chunk_0001', NULL, 1, NULL, 'text', 'paper_045_iclr_2026_proceedings_chunk_0001', 'quote', 'Machine learning systems increasingly face requirements to remove entire domains of information—such as toxic language or biases—rather than individual user data. This task presents a dilemma: full removal of the unwanted domain data is computationally expensive, while random partial removal is statistically inefficient. We find that a domain’s statistical influence is often concentrated in a small subset of its data samples, suggesting a path between ineffective partial removal and unnecessary complete removal. We formalize this as distributional unlearning : a framework to select a small subset that balances forgetting an unwanted distribution while preserving a desired one. Using Kullback-Leibler divergence constraints, we derive the exact removal-preservation Pareto frontier for Gaussian distributions and prove that models trained on the edited data achieve corresponding log-loss bou', 'high', 'paper_045_iclr_2026_proceedings_sec_abstract', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_045_ev_002', 'assessment_ai_paper_045_iclr_2026_proceedings', 'paper_045_iclr_2026_proceedings_chunk_0019', NULL, 10, NULL, 'text', 'paper_045_iclr_2026_proceedings_chunk_0019', 'quote', 'Machine unlearning increasingly requires moving beyond individual record deletion to erase the influence of entire subpopulations. We tackled the central dilemma of this task: that full removal is computationally expensive, while naive partial removal is statistically inefficient. We find that a domain’s statistical influence is often concentrated in a small high-impact subset of its samples. We formalized this insight as distributional unlearning , a framework for selecting a small subset of data that optimally balances forgetting an unwanted distribution while preserving a desired one. Our theoretical analysis provided provable guarantees connecting this data-centric approach to downstream model performance, and our experiments validated that a selective, distance-based removal strategy is often more data-efficient than random or full removals across a range of tasks. While our work pr', 'high', 'paper_045_iclr_2026_proceedings_sec_5', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_045_ev_003', 'assessment_ai_paper_045_iclr_2026_proceedings', 'paper_045_iclr_2026_proceedings_chunk_0047', NULL, 32, NULL, 'text', 'paper_045_iclr_2026_proceedings_chunk_0047', 'quote', 'To assess how sensitive our selective deletion procedure is to the choice of feature representation, we conducted an ablation study on CIFAR–10 where we varied only the feature extractor and kept the selection algorithm and training setup fixed. We compare five representations: the default CNN features used in the main paper, ResNet–18 features (both pretrained and trained from scratch), and raw pixel features. For each setting, we measure forget-set accuracy at a deletion budget of 60% (lower is better forgetting). The results are shown in Table 6. Two main observations emerge. First, across standard learned representations (CNN, ResNet– 18 scratch, ResNet–18 pretrained), the forgetting performance is very similar, suggesting that the method is robust once the feature extractor provides a reasonably expressive embedding space. Second, using raw pixels significantly weakens forgetting, c', 'high', 'paper_045_iclr_2026_proceedings_sec_b_3', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_045_ev_004', 'assessment_ai_paper_045_iclr_2026_proceedings', 'paper_045_iclr_2026_proceedings_chunk_0004', NULL, 2, NULL, 'text', 'paper_045_iclr_2026_proceedings_chunk_0004', 'quote', 'Sample-level unlearning. Sample-level unlearning has made impressive strides in fast model updates and formal deletion guarantees (Neel et al., 2021; Zhang et al., 2024a; Chien et al., 2024; Allouah et al., 2025; Koloskova et al., 2025). Izzo et al. (2021) use influence-function updates to approximate the effect of deleting a single point without full retraining; Guo et al. (2020) provide certified bounds on how close the post-deletion model is to a scratch-retrained one; Bourtoule et al. (2021) employ data sharding to efficiently erase small batches. However, this class of methods does not address which or how many samples must be removed to eliminate a domain’s overall statistical footprint. Our work complements these techniques by asking not just how to update a model once samples are flagged, but which samples to flag in the first place, and in what quantity. Concept erasure. Concept', 'high', 'paper_045_iclr_2026_proceedings_sec_1_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_045_ev_005', 'assessment_ai_paper_045_iclr_2026_proceedings', 'paper_045_iclr_2026_proceedings_chunk_0041', NULL, 29, NULL, 'text', 'paper_045_iclr_2026_proceedings_chunk_0041', 'quote', 'We evaluate five sample-level unlearning strategies that represent different approaches to machine unlearning:

• R ETRAINING (oracle baseline):

– Description: Complete retraining from scratch on the retained data only. It trains a new model from random initialization using only samples from p . It provides the theoretical upper bound for sample-level unlearning performance, representing the gold standard but with highest computational cost. – Hyperparameters: Adam optimizer, learning rate 1 × 10 − 3 , 10 epochs, batch size 128.

• F INE - TUNING (naive baseline):

– Description: Continues training the pre-trained model on retained data only. We initialize with pre-trained weights, then train for additional epochs on non-removed samples. – Hyperparameters: Adam optimizer, learning rate 5 × 10 − 4 , 2 epochs, batch size 128.

• S AL U N (saliency-based unlearning (Fan et al., 2024)):

– ', 'high', 'paper_045_iclr_2026_proceedings_sec_b_2_2', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_045_ev_006', 'assessment_ai_paper_045_iclr_2026_proceedings', 'paper_045_iclr_2026_proceedings_chunk_0002', NULL, 1, NULL, 'text', 'paper_045_iclr_2026_proceedings_chunk_0002', 'quote', 'As machine learning models persist in production, the data on which they were trained often becomes legally or ethically objectionable, requiring deletion. The nature of these requests is now scaling beyond individual user data towards erasing entire subpopulations, which can represent unwanted domains, concepts, or any data-defined construct, e.g., harmful biases or toxic language (Kurmanji et al., 2024). This new scale of unlearning presents a dilemma. On one hand, removing the full set of domain data involves a prohibitive cost, since the computational cost of efficient removal methods typically scales with the size of the forget set (Guo et al., 2020). This challenge is highlighted in efforts to unlearn creative works like the Harry Potter book series (Eldan & Russinovich, 2023), where the sheer size of the identified text and the trained model make the subsequent unlearning action c', 'high', 'paper_045_iclr_2026_proceedings_sec_1', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_045_ev_007', 'assessment_ai_paper_045_iclr_2026_proceedings', 'paper_045_iclr_2026_proceedings_chunk_0013', NULL, 7, NULL, 'text', 'paper_045_iclr_2026_proceedings_chunk_0013', 'quote', 'Having validated our theoretical predictions in a controlled setting, we now test our framework’s applicability on high-dimensional non-Gaussian data. We present two case studies representing distinct unlearning scenarios. We first analyze the CIFAR-10 dataset (Krizhevsky et al., 2014) to test our framework on well-separated distributions, showing it generalizes standard class unlearning. We then turn to the Jigsaw toxic comments dataset 1 for the more challenging scenario of intertwined distributions, where the unwanted domain is semantically linked to the main task. Removalmethods. Acrossbothcasestudies, weevaluateseveralscoringheuristicsdesignedtorank samples in the unwanted distribution p for selective removal. These heuristics are high-dimensional analogues inspired by the principles developed in our theoretical analysis. The choice of distance metric is adapted to the data modality', 'high', 'paper_045_iclr_2026_proceedings_sec_4_2', NULL, FALSE)
ON CONFLICT DO NOTHING;

INSERT INTO evidence_references (evidence_id, assessment_id, chunk_id, element_id, page_number, section_title, locator_type, locator_label, evidence_mode, excerpt, location_confidence, section_id, location_caveat, is_absence_evidence)
VALUES ('paper_045_ev_008', 'assessment_ai_paper_045_iclr_2026_proceedings', 'paper_045_iclr_2026_proceedings_chunk_0046', NULL, 31, NULL, 'text', 'paper_045_iclr_2026_proceedings_chunk_0046', 'quote', 'All experiments were run on a HPE DL380 Gen10 equipped with two Intel(R) Xeon(R) Platinum 8358P CPUs running at 2.60GHz, 128 GB of RAM, a 740 GB SSD, and two NVIDIA A10 GPUs. Training for vision experiments was implemented in PyTorch, while text-based experiments used Scikit-learn. All experiments were conducted using a single GPU.', 'high', 'paper_045_iclr_2026_proceedings_sec_b_2_7', NULL, FALSE)
ON CONFLICT DO NOTHING;

