INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_047_iclr_2025_proceedings_descriptor_001', 'paper_047_iclr_2025_proceedings', 'research_problem', 'problem_statement', 'High quality annotations are increasingly a bottleneck in the explosively growing machine learning ecosystem. Scalable evaluation methods that avoid costly annotation have therefore become an important research ambition. Many hope to use strong existing models in lieu of costly labels to provide cheap model evaluations. Unfortunately, this method of using models as judges introduces biases, such as self-preferencing, that can distort model comparisons. An emerging family of debiasing tools promises to fix these issues by using a few high quality labels to debias a large number of model judgments. In this paper, we study how far such debiasing', 'paper_047_iclr_2025_proceedings_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_047_iclr_2025_proceedings_descriptor_002', 'paper_047_iclr_2025_proceedings', 'contributions', 'claimed_contribution', 'High quality annotations are increasingly a bottleneck in the explosively growing machine learning ecosystem. Scalable evaluation methods that avoid costly annotation have therefore become an important research ambition. Many hope to use strong existing models in lieu of costly labels to provide cheap model evaluations. Unfortunately, this method of using models as judges introduces biases, such as self-preferencing, that can distort model comparisons. An emerging family of debiasing tools promises to fix these issues by using a few high quality labels to debias a large number of model judgments. In this paper, we study how far such debiasing', 'paper_047_iclr_2025_proceedings_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

