INSERT INTO papers (paper_id, title, authors, authors_status, language, arxiv_id, openreview_forum_id, venue, publication_year, abstract, doi)
VALUES ('paper_049', 'Differentiable Integer Linear Programming', '["Geng, Zijie", "Wang, Jie", "Li, Xijun", "Zhu, Fangzhou", "HAO, Jianye", "Li, Bin", "Wu, Feng"]'::jsonb, 'verified', 'en', NULL, NULL, 'ICLR', 2025, 'Machine learning techniques have shown great potential in generating high-quality solutions for integer linear programs (ILPs), but supervised approaches require expensive solver-generated labels and may produce infeasible solutions. The paper proposes DiffILO, an unsupervised learning paradigm that reformulates discrete constrained ILPs as continuous, almost-everywhere differentiable, unconstrained optimization problems. This enables simultaneous problem solving and model training through gradient descent without traditional solver labels. Experiments on common ILP datasets report an average 13.2-times training speedup over supervised methods together with higher feasibility ratios and improved solution quality.', NULL)
ON CONFLICT DO NOTHING;

