INSERT INTO paper_semantic_descriptors (descriptor_id, paper_version_id, descriptor_group, descriptor_type, descriptor_text, evidence_chunk_id, evidence_element_id, confidence)
VALUES ('paper_049_iclr_2025_proceedings_descriptor_001', 'paper_049_iclr_2025_proceedings', 'research_problem', 'problem_statement', 'Machine learning (ML) techniques have shown great potential in generating highquality solutions for integer linear programs (ILPs). However, existing methods typically rely on a supervised learning paradigm, leading to (1) expensive training cost due to repeated invocations of traditional solvers to generate training labels, and (2) plausible yet infeasible solutions due to the misalignment between the training objective (minimizing prediction loss) and the inference objective (generating high-quality solutions). To tackle this challenge, we propose DiffILO ( Diff erentiable I nteger L inear Programming O ptimization), an unsupervised learnin', 'paper_049_iclr_2025_proceedings_chunk_0001', NULL, 'medium')
ON CONFLICT DO NOTHING;

